sp=importlib.util.spec_from_file_location('land',R/'author-land4.py');land=importlib.util.module_from_spec(sp);sp.loader.exec_module(land);p=land.p
land.urls.update(primogeniture='https://www.cnrtl.fr/definition/primog%C3%A9niture',apanage='https://www.cnrtl.fr/definition/apanage',douaire='https://www.cnrtl.fr/definition/douaire',dot='https://www.cnrtl.fr/definition/dot')
land.pr('primogeniture-definition','primogeniture','DR., definition','Antériorité, priorité de naissance entre frères et sœurs entraînant certains droits, en particulier des droits de succession et d\'héritage.')
land.pr('primogeniture-history','primogeniture','Etymologie et histoire','Empr. au lat. médiév. primogenitura « aînesse » (1169 ds Latham , ca 1225 ds NED, 1291 ds Du Cange )')
land.pr('apanage-definition','apanage','Definition','Fief concédé à un prince du sang, en compensation de ce que l\'aîné seul succédait à la couronne.')
land.pr('apanage-reversion','apanage','Etymologie et histoire, 1315','donation surtout territoriale faite aux fils puînés de France pour leur entretien, la couronne se réservant la propriété suprême des pays concédés et le droit de réversion en cas d\'extinction de la postérité masculine')
land.pr('douaire-definition','douaire','DR. ANC., definition','Droit d\'usufruit sur ses biens qu\'un mari assignait à sa femme par son mariage et dont elle jouissait si elle lui survivait.')
