proofs=land.proofs
U='https://magnacarta.cmp.uea.ac.uk/read/magna_carta_1215/Clause_'
def magna(key,n,quote):
 f=R/f'sources/uea-magna-{n}.html';a=p.Text();a.feed(f.read_text());assert quote in ' '.join(' '.join(a.parts).split())
 proofs[key]={'sourceClass':'Medieval primary charter, 1215 text and translation in academic Magna Carta Project at University of East Anglia','title':'Magna Carta 1215, clause '+str(n),'url':U+f'{n:02d}?com=sec','rawCapture':'sources/'+f.name,'captureFormat':'HTML original bytes','captureMethod':'Complete successful HTTP200 response, curl --compressed; original HTML contains full Latin clause and scholarly English translation.','locator':'Translation of clause '+str(n),'passage':quote}
magna('magna7',7,'After the death of her husband a widow is to have her marriage portion and inheritance immediately and without difficulty, nor is she to give anything for her dower, or for her marriage portion, or for the inheritance which she and her husband held on the day of his death, and she may remain in her husband’s house for forty days after his death, during which she is to be assigned her dower.')
magna('magna8',8,'No widow is to be distrained to marry while she wishes to live without a husband, as long as she gives security that she will not marry without our consent, if she holds of us, or without the consent of her lord of whom she holds, if she holds of someone else.')
edits={
'middle-ages-primogeniture':{'prompt':'Какое правило наследования обозначает термин «примогенитура», употреблявшийся в средневековом праве?','answers':[{'text':'Выделение земельного удела младшему члену династии','note':'Для младших членов правящего дома предназначался апанаж: он компенсировал преимущество старшего при наследовании короны.'},{'text':'Передача имущества со стороны невесты при браке','note':'Имущество, которое женщина приносила при вступлении в брак, называлось приданым.'},{'text':'Предоставление жене содержания на случай вдовства','note':'Во французском старом праве douaire давал жене право пользования выделенным имуществом мужа, если она его переживала.'},{'text':'Преимущество старшего ребёнка перед младшими при наследовании','note':'Средневековое латинское primogenitura засвидетельствовано уже в XII веке.'}],'explanation':'Примогенитура связывает преимущество в наследовании со старшинством рождения. Она отличается от обеспечения младших членов семьи отдельным уделом.','source':{'title':'CNRTL / TLFi — primogéniture','url':land.urls['primogeniture'],'verifiedAt':'2026-10-11'}},
'middle-ages-appanage':{'prompt':'Что представлял собой апанаж во французском королевском доме Средневековья?','answers':[{'text':'Преимущество старшего ребёнка при наследовании','note':'Примогенитура связывала преимущество в наследовании со старшинством рождения среди братьев и сестёр.'},{'text':'Имущество, передаваемое невестой при вступлении в брак','note':'Такое имущество называлось приданым; во французской терминологии ему соответствует dot.'},{'text':'Право жены на имущество мужа на случай вдовства','note':'Douaire давал пережившей мужа жене право пользования назначенным ей имуществом.'},{'text':'Земельный удел для младшего члена правящей династии','note':'При прекращении мужской линии получателя французский апанаж должен был вернуться к короне.'}],'explanation':'Апанаж был земельным обеспечением младшего члена династии. Он компенсировал то, что корону наследовал старший, а верховные права на пожалованные земли сохранялись за короной.','source':{'title':'CNRTL / TLFi — apanage','url':land.urls['apanage'],'verifiedAt':'2026-10-11'}},
'middle-ages-dower':{'prompt':'Что Великая хартия вольностей 1215 года устанавливала о получении вдовой её вдовьей доли?','answers':[{'text':'Она получала долю без платы за её выдачу','note':'Для выделения доли отводилось сорок дней после смерти мужа; на это время вдова могла оставаться в его доме.'},{'text':'Она получала долю лишь после нового замужества','note':'Статья 8 позволяла вдове оставаться незамужней; при новом браке сохранялось требование согласия её сеньора.'},{'text':'Её долю заменяли ежегодным жалованьем от короля','note':'Статья 7 требовала выделить вдовью долю и отдельно называла брачную долю и наследство, а не королевское жалованье.'},{'text':'Её долю целиком передавали старшему сыну','note':'Статья 7 закрепляла получение доли самой вдовой; она не передавала это право старшему сыну.'}],'explanation':'Хартия запрещала брать плату за выдачу вдовьей доли. Это правило было закреплено в статье 7 вместе с правом вдовы без промедления получить брачную долю и наследство.','source':{'title':'The Magna Carta Project — 1215, clause 7','url':U+'07?com=sec','verifiedAt':'2026-10-11'}}}
