def emit():
 topic=json.loads(p.TOPIC.read_text());by={c['id']:c for c in topic['questions']};receipt={'role':'author','agentIdentity':os.environ['CODEX_THREAD_ID'],'status':'AUTHOR_CANDIDATE_ONLY; not independent certification','cards':[]}
 for qid,edit in edits.items():
  c=by[qid];c.update(edit);v,editorial,rows=reads[qid];rec={'questionId':qid,'cardCanonicalSha256':p.digest(p.canon(c)),'verdict':v,'editorialAnalysis':editorial,'literalSnapshot':c,'grammarSubstitutions':[c['prompt']+' — '+a['text']+'.' for a in c['answers']],'fields':[]}
  for name,v,read,analysis,refs in rows:
   lit=[c['prompt'],c['correctIndex'],c['answers'][c['correctIndex']]['text']] if name=='prompt-key' else c['explanation'] if name=='explanation' else c['answers'][int(name[-1])]['note'];f={'field':name,'verdict':v,'substantiveRead':read,'claimAnalysis':analysis,'literal':lit,'literalSha256':p.digest(p.canon(lit) if isinstance(lit,list) else lit.encode()),'proofs':[]}
   for ref in refs:
    pr=dict(proofs[ref]);pr.update(proofId=ref,rawCaptureSha256=p.digest((R/pr['rawCapture']).read_bytes()),passageSha256=p.digest(pr['passage'].encode()));f['proofs'].append(pr)
   rec['fields'].append(f)
  receipt['cards'].append(rec)
 p.TOPIC.write_text(json.dumps(topic,ensure_ascii=False,indent=2)+'\n');(R/'author-inheritance3.json').write_text(json.dumps(receipt,ensure_ascii=False,indent=2)+'\n');(R/'inheritance3-candidate.json').write_text(json.dumps([by[x] for x in edits],ensure_ascii=False,indent=2)+'\n')
if __name__=='__main__':emit()
